insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '9732f057-4a7f-45aa-9925-b9522062d11f', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'semantica-y-lexico'),
  (select id from public.lotes where codigo = '2026-B'),
  'e3d7abe2-dc46-49d2-8ea6-f33229c681dc', 'Semántica y léxico',
  'Considere el siguiente enunciado del quinto párrafo: «no sería posible reflexionar sobre nuestras experiencias». En este contexto, ¿a qué se refiere la palabra «posible»?',
  array['A la capacidad humana de razonar.', 'A la capacidad de reflexionar sobre la razón.', 'A la capacidad humana de tener experiencias.', 'A la capacidad de reflexionar sobre las experiencias propias.'],
  'Identifica qué acción acompaña directamente a «posible».', 'publicada', 'modelo', '62d0134c6f9836e1a95fc1be59618570', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9732f057-4a7f-45aa-9925-b9522062d11f', 3, 'En la oración, lo que sería o no posible es reflexionar sobre las experiencias propias. La razón es la condición que permite esa actividad; tener experiencias no equivale a reflexionar sobre ellas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '45aa1c7e-4b2a-4dc5-bff8-d717c01a240f', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'funcion-de-expresiones'),
  (select id from public.lotes where codigo = '2026-B'),
  'e3d7abe2-dc46-49d2-8ea6-f33229c681dc', 'Función de expresiones',
  'En el cuarto párrafo, en el enunciado «Raro... Sin embargo, no tendríamos problema en creer que esa persona está actuando por razones», la expresión «sin embargo» cumple la función de',
  array['señalar una contradicción entre la idea anterior y la siguiente.', 'introducir una razón en contra de la idea anterior.', 'contrastar una idea expuesta anteriormente.', 'mostrar una excepción a una idea.'],
  'Separa tener razones de tener buenas razones.', 'publicada', 'modelo', 'c3498097d9eae5e31acaad899db1dddf', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('45aa1c7e-4b2a-4dc5-bff8-d717c01a240f', 2, 'Contrasta lo extraño o erróneo de las razones con el hecho de que siguen siendo razones. No se niega que sean extrañas; se distingue su calidad de la capacidad de razonar.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '5511380a-2262-4f1a-a64b-94c2d1eabe1e', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'funcion-de-expresiones'),
  (select id from public.lotes where codigo = '2026-B'),
  'e3d7abe2-dc46-49d2-8ea6-f33229c681dc', 'Función de expresiones',
  'En el texto, la autora cita la tesis de Aristóteles para',
  array['desarrollarla, pues aporta evidencia que prueba que la razón es central para el ser humano.', 'contradecirla, ya que el filósofo rechaza la idea de que los seres humanos pueden ser irracionales.', 'presentar el punto de vista del filósofo, ya que está completamente de acuerdo con él.', 'reforzar su propuesta apelando a otro pensador, sin comprometerse con la idea de que la razón es exclusiva de los humanos.'],
  'Ten en cuenta la reserva que aparece después de la cita.', 'publicada', 'modelo', '089d139bc2d3affe888bb8f6b1c63daf', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('5511380a-2262-4f1a-a64b-94c2d1eabe1e', 3, 'La autora aclara «sin tomar parte en este debate» y retiene la centralidad de la razón para el ser humano. No adopta expresamente la exclusividad afirmada por Aristóteles.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '5266f186-9842-471b-b337-8ebc097350dc', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'evaluacion-critica'),
  (select id from public.lotes where codigo = '2026-B'),
  'e3d7abe2-dc46-49d2-8ea6-f33229c681dc', 'Evaluación crítica',
  'Considere la definición de la palabra «irracional» que aparece en el Diccionario de la Real Academia de la Lengua Española (RAE): «Irracional. Que no tiene la facultad de razonar». ¿Cuál es la relación entre la definición del Diccionario y la propuesta del texto acerca de qué es ser irracional?',
  array['La definición de la RAE es incompatible con lo que se propone en el texto sobre la irracionalidad.', 'La definición de la RAE es compatible con lo que se propone en el texto sobre la irracionalidad.', 'La definición de la RAE es una versión abreviada de lo que se propone en el texto sobre la irracionalidad.', 'La definición de la RAE complementa lo que se propone en el texto sobre la irracionalidad.'],
  'Compara la ausencia de facultad con su uso equivocado.', 'publicada', 'modelo', '757c330ba21b45ff88c5d9edd22ead09', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('5266f186-9842-471b-b337-8ebc097350dc', 0, 'En la definición citada falta la facultad de razonar; en el texto, actuar irracionalmente presupone poder razonar, pero hacerlo con razones equivocadas. La autora reserva «no-racional» para lo que no razona.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '40d12e22-ade5-47fd-bb8a-e9b2dbd9bd5b', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  'e3d7abe2-dc46-49d2-8ea6-f33229c681dc', 'Inferencia',
  'Considere el siguiente fragmento: «Un humano con la creencia y el deseo mencionados podría tener una razón para estar allí sin hacer nada, pero ¿una taza de café?». ¿Cuál de las siguientes opciones tiene el mismo sentido que este fragmento?',
  array['Tiene sentido que un ser racional actúe como consecuencia de sus razonamientos, pero es absurdo que un objeto inanimado actúe por razones.', 'Es absurdo que los humanos actúen sin tener razones para hacerlo. Es igualmente absurdo que los objetos inanimados razonen.', 'Es posible que un humano razone de manera extraña, pero es imposible que los demás animales o los objetos inanimados razonen.', 'Es imposible que un ser racional crea y desee cosas absurdas. Es improbable que un ser no-racional tenga deseos o creencias.'],
  'Evita añadir afirmaciones sobre animales o sobre todos los actos humanos.', 'publicada', 'modelo', 'e2b7de5004dac94018ec96bca2ca64e6', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('40d12e22-ade5-47fd-bb8a-e9b2dbd9bd5b', 0, 'El fragmento admite razones en una persona y cuestiona atribuirlas a una taza. No afirma que todo acto humano tenga razones ni resuelve si otros animales razonan.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'd0374926-c668-4c94-9071-b8c77d87b52f', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'funcion-de-expresiones'),
  (select id from public.lotes where codigo = '2026-B'),
  'a48896ff-f07f-4856-95a7-7d235e347a84', 'Función de expresiones',
  'Considere el siguiente fragmento del texto: «En la Unión Soviética había unas setenta mil personas que supervisaban las actividades de unos siete mil escritores. Sin embargo, la proporción entre censores y escritores en Sudáfrica era, en todo caso, superior a diez a uno». ¿Qué indica, en este fragmento, la expresión «Sin embargo»?',
  array['Que lo que viene a continuación de la expresión en cuestión es un argumento a favor de lo dicho en la oración que está antes de la expresión.', 'Que a pesar de la cantidad de censores existentes de la Unión Soviética, en Sudáfrica la censura era más intensa en términos proporcionales.', 'Que a pesar de la enorme cantidad de escritores existentes en la Unión Soviética, en Sudáfrica el número era mayor en términos proporcionales.', 'Que la oración que está antes de la expresión en cuestión es un argumento a favor de lo dicho en la oración que está después de la expresión.'],
  'Compara razones entre censores y escritores, no solo cantidades absolutas.', 'publicada', 'modelo', 'be0c4e61e9f627aa18991d1db64e5785', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('d0374926-c668-4c94-9071-b8c77d87b52f', 1, 'La Unión Soviética tenía diez censores por escritor según las cifras citadas. El conector introduce una proporción todavía mayor en Sudáfrica, pese a la magnitud del primer dato.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '9279409c-1131-44b7-8ba5-ea5da8d284df', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'funcion-de-expresiones'),
  (select id from public.lotes where codigo = '2026-B'),
  'a48896ff-f07f-4856-95a7-7d235e347a84', 'Función de expresiones',
  '¿Cuál es el propósito del autor al citar a Reinaldo Arenas?',
  array['Argumentar que en Sudáfrica, como en Cuba, existían casos de autocensura y autorrepresión.', 'Señalar que en la Unión Soviética, como en Cuba, existía la autocensura y la autorrepresión.', 'Argumentar que los sistemas de censura no eran exclusivos de Sudáfrica y la Unión Soviética.', 'Señalar que en Sudáfrica y la Unión Soviética la censura es mucho más fuerte que en Cuba.'],
  'Lee la oración que introduce a Arenas.', 'publicada', 'modelo', '35299b366d2da60704d0f7d94f00ed2e', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9279409c-1131-44b7-8ba5-ea5da8d284df', 2, 'La cita sigue a la afirmación de que los dos países no eran casos únicos. Cuba aporta otro caso y muestra hasta dónde puede llegar la vigilancia interiorizada.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '042d2507-7407-494a-8fa6-6fb936b07fd5', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  'a48896ff-f07f-4856-95a7-7d235e347a84', 'Estructura y articulación del texto',
  '¿Cómo se califican los hechos narrados en el texto?',
  array['Como reales, ya que se narra una serie de situaciones de tipo histórico.', 'Como fantásticos, ya que hacen parte de las narraciones de escritores.', 'Como irreales, debido a que han pasado por el examen de una censura.', 'Como periodísticos, porque hacen parte de lo narrado en una crónica.'],
  'Observa las referencias a lugares, períodos y prácticas institucionales.', 'publicada', 'modelo', '78cd3002c19f9daca609a59d82d7b48f', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('042d2507-7407-494a-8fa6-6fb936b07fd5', 0, 'Se presentan sistemas de censura situados en países y períodos históricos. Citar escritores no convierte esos hechos en fantasía.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '65575fbd-a095-4c0d-ac7c-c15c02aa9146', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  'a48896ff-f07f-4856-95a7-7d235e347a84', 'Inferencia',
  'De acuerdo con el texto, ¿por qué en Cuba había un ambiente de «amenaza oficial»?',
  array['Porque los individuos no solo eran objeto de represión, sino que se autorreprimían.', 'Porque allí se aplicó uno de los sistemas de censura más exhaustivos del mundo.', 'Porque las personas no solo eran atacadas, sino también censuradas.', 'Porque este país estaba repleto de mensajes codificados.'],
  'Usa la caracterización específica que acompaña la expresión sobre Cuba.', 'publicada', 'modelo', '71cfffeb9b1d7dcf6a6e5e746e725ba0', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('65575fbd-a095-4c0d-ac7c-c15c02aa9146', 0, 'La cita caracteriza ese ambiente mediante la represión que se vuelve autorrepresión, autocensura y vigilancia de uno mismo. La descripción de un sistema particularmente exhaustivo se refiere antes a Sudáfrica.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '044824b7-b739-4667-bac3-6087f07cab99', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  'a48896ff-f07f-4856-95a7-7d235e347a84', 'Estructura y articulación del texto',
  'Considere el fragmento: «No sólo los libros, las revistas, las películas y las obras teatrales, sino también las camisetas, los llaveros, las muñecas, los juguetes y los letreros de las tiendas —en realidad, cualquier cosa portadora de un mensaje que pudiera ser indeseable— tenían que someterse al análisis de los censores antes de poder hacerse públicos». ¿Cuál es la función que cumple este fragmento en el primer párrafo?',
  array['Exponer la tesis central del texto según la cual las personas no son solo censuradas sino también autocensuradas.', 'Mostrar ejemplos para ilustrar por qué la paranoia es uno de los rasgos más distintivos de las dictaduras modernas.', 'Mostrar ejemplos que ilustran por qué el sistema de censura sudafricano fue uno de los más severos del mundo.', 'Exponer la tesis central del texto según la cual la paranoia es la enfermedad de los gobiernos inseguros.'],
  'Relaciona la lista con la primera oración del párrafo.', 'publicada', 'modelo', 'e6e40168fdd18aca8ec6e56035d0fd9a', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('044824b7-b739-4667-bac3-6087f07cab99', 2, 'La enumeración muestra cuántas clases de objetos eran examinadas y concreta la afirmación inicial sobre la exhaustividad del sistema sudafricano.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '00c62e6b-b0ea-4dae-8f14-8c6c776f2585', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'tesis-y-argumentos'),
  (select id from public.lotes where codigo = '2026-B'),
  '74e17d04-ff95-4060-92de-1ac2e83cb1a0', 'Tesis y argumentos',
  '¿Por qué el autor está de acuerdo con la frase citada por Edgar Allan Poe?',
  array['Porque escribir es organizar ideas para fomentar el pensamiento.', 'Porque escribir sobre ideas y sentimientos es sinónimo de pensamiento.', 'Porque escribir permite la creación de nuevo pensamiento.', 'Porque escribir es de hecho el único medio para crear pensamiento.'],
  'Toma en cuenta la precisión de la última oración.', 'publicada', 'modelo', '40e0afaf67e606f222421f1b8a9668f1', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('00c62e6b-b0ea-4dae-8f14-8c6c776f2585', 2, 'El autor termina diciendo que escribir crea pensamiento y distingue esa función de organizar ideas o revelar sentimientos. No sostiene que sea el único medio posible.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'fe5de349-968c-433b-844b-6e5fbdebba0f', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'evaluacion-critica'),
  (select id from public.lotes where codigo = '2026-B'),
  '74e17d04-ff95-4060-92de-1ac2e83cb1a0', 'Evaluación crítica',
  '¿Qué comportamiento es criticado por el autor del texto?',
  array['La costumbre de la mayoría de escritores de querer estar en silencio.', 'La falta de solidaridad del público al pedir sociabilidad a autores tímidos.', 'La exigencia a los escritores de que sean conversadores inteligentes.', 'La impertinencia de la gente al decir que es posible pensar sin escribir.'],
  'Identifica qué expectativa inicial reconsidera.', 'publicada', 'modelo', '1b9cfeead63e81218c0d531f3c4521db', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('fe5de349-968c-433b-844b-6e5fbdebba0f', 2, 'El autor abandona su decepción inicial al reconocer que la calidad de la escritura no obliga a ser un conversador brillante. Esa exigencia es lo que cuestiona.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '64b546d1-0b23-4515-bf43-826ac3ccc51a', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  'dea57fe5-c828-4ca9-a398-b83be912cead', 'Estructura y articulación del texto',
  '¿Cuántas voces intervienen en la narración del texto anterior?',
  array['Ninguna, pues lo que dicen los personajes que aparecen en la historia no se presenta.', 'Una: la voz del narrador no identificado que relata la historia.', 'Dos: la voz del lector de la novela que aparece en la historia y la del narrador de esa novela.', 'Cuatro: las voces de los dos amantes, la del lector de la novela y la del jardinero, que aparecen en la historia.'],
  'Distingue los personajes de la voz que cuenta.', 'publicada', 'modelo', '2e47e9a157f91167ab5c3df98a59fe5d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('64b546d1-0b23-4515-bf43-826ac3ccc51a', 1, 'Un mismo narrador en tercera persona presenta al lector y a los amantes. La presencia de varios personajes no implica que cada uno narre.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '554f8dd6-e510-4648-942d-c6c01f161ddf', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  'dea57fe5-c828-4ca9-a398-b83be912cead', 'Estructura y articulación del texto',
  '¿Cuál de los objetos descritos en el cuento se relaciona con el título?',
  array['Un arroyo de serpientes.', 'La luz de los ventanales.', 'Una cuestión de aparcerías.', 'El jardín de robles de la finca.'],
  'Busca la referencia espacial a los parques.', 'publicada', 'modelo', 'ab9f0a1a225b1eaf2d3f8f95b59281d8', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('554f8dd6-e510-4648-942d-c6c01f161ddf', 3, 'El parque de robles sitúa el espacio al que se enlaza la escena de los amantes; es el objeto mencionado que corresponde al título.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '36c04de5-f6bd-4d1a-9694-1e08597dc9af', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  'c35b73e2-2c07-4643-94fa-761400aede24', 'Estructura y articulación del texto',
  'Considere el siguiente enunciado del primer párrafo: «Durante este tiempo preparan el horóscopo del futuro niño y se entregan a la meditación».',
  array['los padres de los futuros niños.', 'los vendedores de nombres.', 'los compradores de las tienduchas.', 'los seguidores de Buda.'],
  'El enunciado original está incompleto.', 'borrador', 'modelo', '7b3792fc7c7f95f27c087a2fdb4fd5a8', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('36c04de5-f6bd-4d1a-9694-1e08597dc9af', 1, 'La fuente omite la pregunta después de la cita. Los vendedores preparan el horóscopo, pero no se puede suponer que identificar ese sujeto sea lo que pide el enunciado. Se conserva fuera de práctica hasta revisión docente.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'ee6c4749-588f-4630-937b-f3869847e425', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'informacion-literal'),
  (select id from public.lotes where codigo = '2026-B'),
  'c35b73e2-2c07-4643-94fa-761400aede24', 'Información literal',
  '¿En cuál de los siguientes lugares ocurren los hechos descritos?',
  array['En una sala de partos.', 'En una plaza de mercado.', 'Entre templos budistas.', 'Entre tiendas callejeras.'],
  'Relee la localización de la primera oración.', 'publicada', 'modelo', 'ebccc54f9c0453e639ef5be169276df2', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('ee6c4749-588f-4630-937b-f3869847e425', 3, 'La primera oración sitúa las tienduchas en una calle. Las estatuillas de Buda son objetos en las tiendas, no convierten el lugar en un templo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '5f106158-e4c6-4602-8645-114de77c7dd2', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'informacion-literal'),
  (select id from public.lotes where codigo = '2026-B'),
  'c35b73e2-2c07-4643-94fa-761400aede24', 'Información literal',
  'Según el texto, la asignación de nombres se puede caracterizar como una',
  array['superstición antigua que ha sido abandonada.', 'tarea religiosa realizada por monjes budistas.', 'responsabilidad que recae solo en los padres.', 'actividad comercial realizada por especialistas.'],
  'Identifica quién presta el servicio y a quién.', 'publicada', 'modelo', '6ca41621e1c44e9572de4c0f4d3f2c33', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('5f106158-e4c6-4602-8645-114de77c7dd2', 3, 'Hay vendedores, clientes y competencia, y los vendedores emplean técnicas especializadas. El relato presenta una actividad comercial vigente.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '48b2895d-c371-4042-8f00-a860d39bfd6e', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'evaluacion-critica'),
  (select id from public.lotes where codigo = '2026-B'),
  'c35b73e2-2c07-4643-94fa-761400aede24', 'Evaluación crítica',
  'Tenga en cuenta este resumen del texto: En cierto lugar, los padres, una vez que han bautizado a su hijo, acuden a tienduchas de adivinos. Entre estatuas de Brahma y montañas de papeles de arroz caligrafiados, los adivinos consultan el horóscopo para determinar si el nombre asignado por sus progenitores le trae buen augurio al bebé. Si la respuesta es negativa, los padres marchan a la competencia por una segunda opinión. El anterior resumen es',
  array['completo, ya que aporta la información esencial del texto.', 'incompleto, ya que omite detalles relevantes del relato.', 'incorrecto, ya que presenta hechos que no son narrados.', 'correcto, ya que recoge los eventos primordiales de la narración.'],
  'Contrasta los hechos del resumen con el primer párrafo.', 'publicada', 'modelo', 'c5eab52a05a58253f6e56ab29e1c3bd6', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('48b2895d-c371-4042-8f00-a860d39bfd6e', 2, 'El relato trata de niños aún no nacidos y de elegir un nombre, no de evaluar uno ya impuesto tras el bautizo. También cambia Buda por Brahma. Son alteraciones, no simples omisiones.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '3ef2b41e-aea6-4b95-ab52-f41fecdffcfe', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  'c35b73e2-2c07-4643-94fa-761400aede24', 'Inferencia',
  'Cuando en el texto se dice «De nada sirve que el vendedor les explique que Buda en persona llamó Traba a su propio hijo», sugiere que',
  array['todo hijo es de cierta forma una traba, pues trae retos y dificultades que sus padres deben superar.', 'incluso un padre sabio y justo como Buda puede nombrar a su hijo de forma desafortunada.', 'Buda era un padre injusto porque le puso a su hijo un nombre poco agradable.', 'Si Buda se equivocó con el nombre de su propio hijo también se pudo equivocar con el de otros niños.'],
  'Interpreta la frase en el contexto del descontento de los compradores.', 'publicada', 'modelo', 'c3827867451389e4312a2b4db20039a4', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3ef2b41e-aea6-4b95-ab52-f41fecdffcfe', 1, 'El ejemplo contrasta la autoridad de Buda con un nombre que los clientes consideran poco agradable. No demuestra que todo hijo sea un obstáculo ni que Buda haya nombrado a otros niños.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'b4cd8b60-4f0e-42cb-95e4-a52f9b09788e', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'tesis-y-argumentos'),
  (select id from public.lotes where codigo = '2026-B'),
  'f30828e9-0262-4f3d-b418-d6b2f4eff774', 'Tesis y argumentos',
  '¿Cuál de los siguientes fragmentos cumple con la función de ejemplificar el concepto de aporofobia?',
  array['Nadie pone reparos a que un jeque árabe se instale en un país europeo, ni a facilitar la residencia a un futbolista famoso.', 'En la palabra «aporofobia» dicha Fundación ha encontrado un término muy significativo, y una rara excepción lingüística: «una voz con autor conocido y fecha de nacimiento».', 'La recesión económica ha intensificado el miedo a la pobreza porque nos ha hecho ver que todos somos vulnerables...', 'Lo ha denominado «aporofobia», un fenómeno que está en el origen de las corrientes xenófobas y racistas que se extienden por el acomodado mundo occidental.'],
  'Busca un caso concreto dentro del contraste entre extranjeros ricos y pobres.', 'publicada', 'modelo', 'c40db7b7723273df7987d4b41c2d32b0', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b4cd8b60-4f0e-42cb-95e4-a52f9b09788e', 0, 'El ejemplo muestra, por contraste, que la riqueza facilita la aceptación de extranjeros: el rechazo descrito se dirige a la pobreza. Las otras citas definen el fenómeno o comentan la palabra y sus causas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'b0e61d1a-df16-4eb4-985e-8f412fbc6a67', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  'f30828e9-0262-4f3d-b418-d6b2f4eff774', 'Inferencia',
  'Considere el siguiente fragmento: «La recesión económica ha exacerbado el miedo a la pobreza porque nos ha hecho ver que todos somos vulnerables...». ¿Qué se puede concluir de la idea expresada en la frase anterior?',
  array['Que no existe ninguna relación entre el contexto de una crisis económica y el creciente temor a la pobreza.', 'Que las crisis económicas son una buena oportunidad para construir una sociedad más justa.', 'Que el trabajo y el esfuerzo serán siempre recompensados y que, por tanto, el que es pobre es pobre porque quiere.', 'Que cualquier persona puede quedarse de repente sin trabajo y sin medios de subsistencia.'],
  'Interpreta a quiénes abarca «todos».', 'publicada', 'modelo', '6a6d34f5316dc3426acec91f6116059d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b0e61d1a-df16-4eb4-985e-8f412fbc6a67', 3, 'La vulnerabilidad general implica que perder los medios de subsistencia no es un riesgo exclusivo de quienes ya son pobres. La frase vincula ese riesgo con el miedo durante una crisis.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '4e0ab9be-fc95-4a51-a328-f0e5e3847475', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'proposito-del-texto'),
  (select id from public.lotes where codigo = '2026-B'),
  '141773c4-5c79-467d-8267-7bc1a60de9b7', 'Propósito del texto',
  '¿Cuál es el tema general de la infografía?',
  array['Algunas ideas erróneas sobre el cerebro.', 'El cerebro humano y sus características.', 'Los malos hábitos que afectan al cerebro.', 'Diferencias entre hemisferios cerebrales.'],
  'Integra los cuatro bloques y el título.', 'publicada', 'modelo', 'c303d3ba4bbcc6c2aa3e69beb88654c3', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4e0ab9be-fc95-4a51-a328-f0e5e3847475', 0, 'El conjunto contrasta cuatro mitos con explicaciones que los corrigen. El tema no se limita a hábitos o hemisferios.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '74c7b734-404b-4d84-9515-fbdff51a9d1a', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'evaluacion-critica'),
  (select id from public.lotes where codigo = '2026-B'),
  '141773c4-5c79-467d-8267-7bc1a60de9b7', 'Evaluación crítica',
  '¿Cuál de las siguientes afirmaciones del texto expresa un prejuicio?',
  array['«El alcohol entorpece la comunicación».', '«El lado izquierdo se encarga de la lógica».', '«El cerebro de la mujer es más emocional».', '«Tu cerebro usa el 100% de su capacidad».'],
  'Distingue el estereotipo social de otras afirmaciones del gráfico.', 'publicada', 'modelo', 'b574391bc7237c698c8e94b76c057335', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('74c7b734-404b-4d84-9515-fbdff51a9d1a', 2, 'Atribuir una forma de pensar a todas las mujeres por su sexo expresa un estereotipo de género. La infografía lo presenta como una creencia que cuestiona.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'a64ac32a-273d-4a98-b522-dfc62a06404e', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  '141773c4-5c79-467d-8267-7bc1a60de9b7', 'Estructura y articulación del texto',
  'En la infografía presentada, ¿qué tipo de relación existe entre el texto y la imagen?',
  array['Hay una relación de oposición, pues el texto se opone a la imagen para generar extrañeza en el lector.', 'Hay una relación de justificación, pues la imagen da evidencias que prueban determinada conclusión.', 'Hay una relación de complementariedad, pues las imágenes representan lo que el texto está diciendo.', 'Hay una relación de jerarquía, ya que el mensaje del texto depende de lo que muestran las imágenes.'],
  'Observa cómo cada dibujo acompaña su explicación.', 'publicada', 'modelo', 'fd03e6aec2e139d791b2cf137161ef14', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a64ac32a-273d-4a98-b522-dfc62a06404e', 2, 'Los dibujos ilustran el contenido verbal de cada mito y su contraste. No constituyen por sí mismos pruebas científicas ni contradicen el mensaje escrito.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '2a4900ae-3326-4657-8c60-6e05d7985f5b', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  '141773c4-5c79-467d-8267-7bc1a60de9b7', 'Estructura y articulación del texto',
  'Considere las siguientes afirmaciones sobre el cerebro, tomadas del cuarto recuadro de la infografía: 1. El lado derecho se encarga de la creatividad. El lado izquierdo se encarga de la lógica. 2. Ambos hemisferios realizan funciones lógicas y creativas. Seleccione la relación que hay entre 1 y 2:',
  array['2 es opuesta a 1.', '2 es semejante a 1.', '2 es un ejemplo de 1.', '2 es una evidencia de 1.'],
  'Compara la exclusividad de la primera con «ambos» en la segunda.', 'publicada', 'modelo', 'bb06ca8c4394fd71894b733b4afc7426', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('2a4900ae-3326-4657-8c60-6e05d7985f5b', 0, 'La segunda niega el reparto exclusivo de funciones que propone la primera. Se presenta como corrección del mito.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '0de278f0-a2ff-443c-b235-6386d37cfc7a', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '141773c4-5c79-467d-8267-7bc1a60de9b7', 'Inferencia',
  'Considere la siguiente afirmación del tercer recuadro de la infografía: «Aunque hay pequeñas diferencias anatómicas, el cerebro de hombres y mujeres funciona igual». ¿Qué se concluye de esta afirmación?',
  array['Que hombres y mujeres tienen habilidades cognitivas algo diferentes.', 'Que hombres y mujeres tienen igual capacidad en cualquier área.', 'Que hombres y mujeres tienen un manejo diferente de las emociones.', 'Que tanto hombres como mujeres tienen el cerebro del mismo tamaño.'],
  'Responde conforme al contraste que establece la infografía.', 'publicada', 'modelo', 'c4a59db148dd1b10c63bdbb8e0766295', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('0de278f0-a2ff-443c-b235-6386d37cfc7a', 1, 'Entre las opciones, la igualdad de capacidad es la que recoge la intención del texto de rechazar una división de habilidades por sexo. La frase es una generalización de la infografía: no afirma que todas las personas tengan capacidades individuales idénticas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '1808fb21-fe51-4e2c-807b-c6368c4cc113', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'funcion-de-expresiones'),
  (select id from public.lotes where codigo = '2026-B'),
  '141773c4-5c79-467d-8267-7bc1a60de9b7', 'Función de expresiones',
  'Considere la oración «El alcohol entorpece la comunicación entre las neuronas, pero difícilmente llegará a matarlas». ¿Cuál es la función del conector «pero» en esta oración?',
  array['Indicar que las dos ideas de la oración son semejantes.', 'Establecer una relación de oposición entre los dos elementos.', 'Señalar que la primera idea es un complemento de la segunda.', 'Comparar las dos ideas como elementos diferentes.'],
  'Identifica el contraste entre afectar la comunicación y matar.', 'publicada', 'modelo', 'd092e6af1acd90ec621ae739709fa58f', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1808fb21-fe51-4e2c-807b-c6368c4cc113', 1, 'El conector introduce una restricción a lo anterior: el efecto descrito no equivale a la consecuencia extrema mencionada después. La pregunta evalúa la función del conector dentro de la frase.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '29cfbbe0-eea4-4f89-953a-720d51eab4da', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'informacion-literal'),
  (select id from public.lotes where codigo = '2026-B'),
  '08bc7e40-c975-4914-86b7-52063b8c4684', 'Información literal',
  'El fragmento del texto que responde la pregunta «¿cómo actúa la solitaria dentro del organismo?» es:',
  array['Pero, todo lo que comía y bebía no era para su gusto y placer, sino para los de la solitaria.', 'Una vez que la solitaria se instala en el organismo se consubstancia con él, se alimenta de él, crece y se fortalece a expensas de él.', 'José María enflaquecía, a pesar de que debía comer y beber líquidos (leche, sobre todo) constantemente para aplacar la ansiedad del animal aposentado en sus entrañas.', 'Nosotros hacemos tantas cosas juntos. Y tú crees que yo estoy haciendo esas cosas como las haces tú, porque te divierte hacerlas. Pero, te equivocas. Yo las hago para ella, la solitaria.'],
  'Busca las acciones cuyo sujeto es la solitaria.', 'publicada', 'modelo', '75903b15650bbc452a84a741f09fce30', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('29cfbbe0-eea4-4f89-953a-720d51eab4da', 1, 'Ese fragmento describe directamente las acciones del parásito en el organismo: alimentarse, crecer y fortalecerse a expensas del huésped. Los demás se centran en la experiencia del personaje.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'b98038f6-7429-445e-97e4-383703c68690', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'semantica-y-lexico'),
  (select id from public.lotes where codigo = '2026-B'),
  '08bc7e40-c975-4914-86b7-52063b8c4684', 'Semántica y léxico',
  'Considere la oración: «Su decisión de asumir su afición por la literatura como un destino, deberá convertirse en servidumbre, en nada menos que esclavitud». ¿Cuál de las siguientes palabras tiene un significado opuesto al de la palabra «afición»?',
  array['Inclinación.', 'Insatisfacción.', 'Pasión.', 'Aversión.'],
  'Busca la palabra que expresa rechazo hacia algo.', 'publicada', 'modelo', '77891aa8c22d1526d2d6160fb4966b70', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b98038f6-7429-445e-97e4-383703c68690', 3, 'Afición expresa gusto o inclinación; aversión, rechazo intenso. Insatisfacción es falta de satisfacción, no el opuesto específico de sentir afición.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '096c2007-6afe-451a-8090-c715d9fd4730', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '08bc7e40-c975-4914-86b7-52063b8c4684', 'Inferencia',
  'Cuando Vargas Llosa compara la decisión de convertirse en escritor con aquella que tomaban las mujeres del siglo XIX (trabarse una solitaria para recobrar la silueta de sílfide), está sugiriendo que convertirse en escritor',
  array['lleva a estar solo, tal como lo estaban las solitarias que vivían dentro de aquellas mujeres.', 'implica ser esclavo de la escritura, tal como esas mujeres se convertían en esclavas de la solitaria.', 'conlleva a vivir una vida de sílfide, tal como llegaban a vivir las mujeres que se tragaban la solitaria.', 'exige literalmente tragarse una solitaria y ser esclavo de ella, tal como aquellas mujeres del siglo XIX.'],
  'Identifica qué rasgo comparten los dos casos.', 'publicada', 'modelo', '7d23f738994605ccb448d88ff3c193cc', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('096c2007-6afe-451a-8090-c715d9fd4730', 1, 'La comparación une dos formas de dependencia: vivir al servicio de la escritura y del parásito. No propone imitar literalmente la ingestión ni equipara «solitaria» con aislamiento.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '7c92bc06-f66b-472d-83a5-b9250dbf431d', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '08bc7e40-c975-4914-86b7-52063b8c4684', 'Inferencia',
  'Considere el siguiente fragmento del texto: «Un día, que estábamos conversando en un pequeño bistrot de Montparnasse, me sorprendió con esta confesión: “Nosotros hacemos tantas cosas juntos. Vamos al cine, a exposiciones, a recorrer librerías, y discutimos horas de horas sobre política, libros, amigos comunes. Y tú crees que yo estoy haciendo esas cosas como las haces tú, porque te divierte hacerlas. Pero, te equivocas. Yo las hago para ella, la solitaria. Esa es la impresión que tengo: que todo en mi vida, ahora, no lo vivo para mí, sino para ese ser que llevo adentro, del que ya no soy más que un sirviente”». El anterior fragmento hace una caracterización de',
  array['la libertad de José María.', 'la esclavitud de José María.', 'la soledad de José María.', 'la inteligencia de José María.'],
  'Relaciona «sirviente» y «no lo vivo para mí».', 'publicada', 'modelo', '651cbdfe0beea8718df3100468d754d0', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7c92bc06-f66b-472d-83a5-b9250dbf431d', 1, 'José María se describe como sirviente y afirma que sus actos están subordinados al parásito. Ese lenguaje caracteriza la dependencia como esclavitud.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '1de4718f-81e2-46f6-a183-6536f6dd9e85', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'tesis-y-argumentos'),
  (select id from public.lotes where codigo = '2026-B'),
  '08bc7e40-c975-4914-86b7-52063b8c4684', 'Tesis y argumentos',
  'Según el autor, la afición por la literatura puede convertirse en esclavitud. ¿Qué estrategia retórica usa el autor para ilustrar esto?',
  array['Contraste.', 'Exageración.', 'Comparación.', 'Cita de autoridades.'],
  'Observa el vínculo entre escribir y vivir con el parásito.', 'publicada', 'modelo', '7dbe34a5204d3297807d13b5a83b797c', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1de4718f-81e2-46f6-a183-6536f6dd9e85', 2, 'El autor compara la dedicación del escritor con la vida de una persona dominada por la solitaria. La anécdota desarrolla esa analogía.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'ee387eb1-57ea-4e70-a616-95864bcd9082', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  'bc192cac-759c-4f40-ab79-8f620497d0e8', 'Estructura y articulación del texto',
  'En el recuadro número 2, la flecha que aparece junto a la frase «y en la base pon 10% de piedra porosa» sirve para:',
  array['Describir el modo en que se pone la lombricomposta.', 'Mostrar lo que se debe hacer con la tierra de hoja.', 'Señalar el lugar en el que se ubica la piedra porosa.', 'Indicar el paso posterior a poner la capa de piedra porosa.'],
  'Sigue la punta de la flecha dentro del recipiente.', 'publicada', 'modelo', 'ac5cda90540e4543d19fb83d0391ef36', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('ee387eb1-57ea-4e70-a616-95864bcd9082', 2, 'La flecha apunta a la parte inferior del recipiente, donde debe ir la piedra porosa. Su función es localizar el material en el dibujo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'fce029d0-96ce-4661-b7fd-c6d8e0b9d456', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'estructura-textual'),
  (select id from public.lotes where codigo = '2026-B'),
  '8cc75776-7b85-4333-9f27-0a548bfec4e2', 'Estructura y articulación del texto',
  'Considere los siguientes dos enunciados del texto: 1) Estos sistemas funcionaban muy bien, pero estaban hechos a la medida de cualquier bromista. 2) Un tirón al cable del salón en cualquier punto de su recorrido era suficiente para que el mayordomo corriera hacia allí, comprobara que la habitación estaba vacía y se quedara con la duda de si había sido llamado o no. ¿Cuál de las siguientes opciones expresa la relación entre 1 y 2?',
  array['1 explica la idea expresada por 2.', '2 cuestiona la idea expresada por 1.', '2 desarrolla la idea expresada por 1.', '1 contradice la idea expresada por 2.'],
  'Distingue la afirmación general de su explicación concreta.', 'publicada', 'modelo', '46bf15706712a3cff1ebc7ebe5d1f601', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('fce029d0-96ce-4661-b7fd-c6d8e0b9d456', 2, 'El segundo enunciado precisa cómo alguien puede producir una llamada engañosa, desarrollando la posibilidad de una broma anunciada en el primero.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '6fd4d6ee-1e4a-48c9-8e64-053043e78a58', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'inferencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '8cc75776-7b85-4333-9f27-0a548bfec4e2', 'Inferencia',
  '¿Cuál de las siguientes opciones presenta una idea similar a la expuesta en el último párrafo del texto?',
  array['El uso de sustancias psicoactivas puede alterar la capacidad de controlar nuestra propia mente.', 'Algunos estudios sugieren que las experiencias alucinatorias son comunes en la población general.', 'Las personas que tienen defectos en la visión pueden tener aumentos en su capacidad auditiva.', 'A veces el cerebro construye sensaciones erróneas cuando no hay un estímulo físico que las produzca.'],
  'Busca la opción que corresponde a la explicación del último párrafo, no a conocimientos externos.', 'publicada', 'modelo', 'd00e2a87c9b02b303821dc6b2af3516c', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6fd4d6ee-1e4a-48c9-8e64-053043e78a58', 3, 'Según el pasaje, una alteración de la cadena nerviosa puede dar lugar a efectos semejantes a una percepción sin que exista el objeto percibido. Esa es la idea que recoge la opción.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '9265a03b-80e0-4239-a3cf-862c4ef58f38', 'lc',
  (select id from public.temas where materia = 'lc' and codigo = 'tesis-y-argumentos'),
  (select id from public.lotes where codigo = '2026-B'),
  '8cc75776-7b85-4333-9f27-0a548bfec4e2', 'Tesis y argumentos',
  'De acuerdo con el texto, ¿cuál de las siguientes estrategias emplea Descartes para defender su explicación de las alucinaciones?',
  array['Una deducción a partir de algunos principios generales sobre el cerebro humano.', 'Una generalización a partir de la observación de numerosos ejemplos de experiencias alucinatorias.', 'Una comparación de los complejos sistemas de cables de las casas grandes con el sistema nervioso.', 'Un análisis de diversos estudios científicos sobre la estructura y funcionamiento del cerebro.'],
  'Identifica el sistema cotidiano que sirve como modelo de la explicación.', 'publicada', 'modelo', '6b7939045186d9d9a73e3f2fa3096d84', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9265a03b-80e0-4239-a3cf-862c4ef58f38', 2, 'El texto explica el sistema nervioso mediante la analogía con cables que activan campanillas: una intervención en la cadena puede generar una señal engañosa.');

